const base = 100;

function quote(hours) {
  const rate = 20;

  function labour() {
    return hours * rate;
  }

  function total() {
    const extra = 5;

    return base + labour() + extra;
  }

  console.log(labour());
  console.log(total());
  console.log(typeof extra);
}

quote(2);
